		List<string> functionTags = info.functionTags;
		if (functionTags == null) {
			throw new InvalidInputException("Function tag does not exist: " + tagName);
		}

		flag = 8;
		foreach (string tag in functionTags) {
			if (tag.endsWith(tagName)) {
				break;
			}
			flag = flag * 2;
		}
	}

